spec.expr:
sum (
    sum by (namespace,pod) (kube_pod_container_resource_requests{resource="memory",node=~"$node"})
    * on(namespace, pod) group_left() max by (namespace, pod) (
        kube_pod_status_phase{phase=~"Pending|Running"} == 1
    )
)

sum (
    sum by (namespace,pod) (kube_pod_container_resource_limits{resource="memory",node=~"$node"})
    * on(namespace, pod) group_left() max by (namespace, pod) (
        kube_pod_status_phase{phase=~"Pending|Running"} == 1
    )
)

sum by(node,type) (
    label_replace(
        sum by(node) (container_memory_working_set_bytes{container!="",node=~"$node"} @ end() * on (namespace,pod) group_left(phase) (kube_pod_status_phase{phase=~"^(Pending|Running|Terminating)$"} == 1))
        ,"type","usage","node",".*"
    )
)

sum by(node,type) (
    label_replace(
        sum by (node) (kube_pod_container_resource_requests{resource="memory",node=~"$node"} * on (namespace,pod) group_left(phase) (kube_pod_status_phase{phase=~"^(Pending|Running|Terminating)$"} == 1))
        ,"type","request","node",".*"
    )
)

sum by(node,type) (
    label_replace(
        sum by(node) (kube_node_status_allocatable{resource="memory",node=~"$node"} @ end())
        ,"type","allocatable","node",".*"
    )
)

avg by(node) (
    avg by(internal_ip) (
        label_replace(
            avg by(instance) (
                node_memory_MemFree_bytes{node=~"$node"}
            ),
            "internal_ip",
            "$1",
            "instance",
            "([^:]+):.*"
        )
    )
    * on(internal_ip) group_right
    kube_node_info{node=~"$node"}
)

avg by(node) (
    avg by(internal_ip) (
        label_replace(
            avg by(instance) (
                node_memory_Cached_bytes{node=~"$node"}
            ),
            "internal_ip",
            "$1",
            "instance",
            "([^:]+):.*"
        )
    )
    * on(internal_ip) group_right
    kube_node_info{node=~"$node"}
)

avg by(node) (
    avg by(internal_ip) (
        label_replace(
            avg by(instance) (
                node_memory_MemFree_bytes{node=~"$node"} + node_memory_Cached_bytes{node=~"$node"}
            ),
            "internal_ip",
            "$1",
            "instance",
            "([^:]+):.*"
        )
    )
    * on(internal_ip) group_right
    kube_node_info{node=~"$node"}
)

avg by(node) (
    avg by(internal_ip) (
        label_replace(
            avg by(instance) (
                node_memory_Buffers_bytes{node=~"$node"}
            ),
            "internal_ip",
            "$1",
            "instance",
            "([^:]+):.*"
        )
    )
    * on(internal_ip) group_right
    kube_node_info{node=~"$node"}
)

sum (
    sum by (namespace,pod) (kube_pod_container_resource_requests{resource="cpu",node=~"$node"})
    * on(namespace, pod) group_left() max by (namespace, pod) (
        kube_pod_status_phase{phase=~"Pending|Running"} == 1
    )
)
